import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c3_out_act_k12.npy')); b=-12.2815
st={'k':0,'delta':None,'K':(0,13),'fires':[]}
def hook(m,inp,out):
    a=inp[0]; s=(a@w+b)>0
    st['fires'].append(s.clone())
    if st['delta'] is not None and st['K'][0]<=st['k']<st['K'][1]:
        out=out+s[:,None].float()*st['delta']
    st['k']+=1
    return out
net.out.register_forward_hook(hook)
def run(xi,c,delta=None,K=(0,13)):
    st.update(k=0,delta=None if delta is None else torch.tensor(delta,dtype=torch.float32),K=K,fires=[])
    a,S,A=model.decode(net,xi,c,save_states=True)
    return np.asarray(a),torch.stack(st['fires']).numpy()
neg=model.negatives(); na=np.asarray(neg['a']); nc=np.asarray(neg['c']); uid=np.array(neg['uid'])
xin=np.asarray(neg['xi'],dtype=np.float32); cn=nc.astype(np.float32)
an,fn=run(xin,cn); memmask=fn[:13].any(0)
# per-negative basin radius scale
